export async function getPosts(revalidate: number, limit?: number): Promise<BlogPost[]> {
  const url = `${baseUrl}/posts${limit ? `?_limit=${limit}` : ''}`
  const response = await fetch(url, { next: { revalidate } })
  if (!response.ok) throw new Error('Failed to load posts')
  return (await response.json()) as BlogPost[]
}

export async function getPost(id: string): Promise<BlogPost | null> {
  const response = await fetch(`${baseUrl}/posts/${encodeURIComponent(id)}`, {
    next: { revalidate: 300 },
  })
  if (response.status === 404) return null
  if (!response.ok) throw new Error('Failed to load post')
  const post = (await response.json()) as BlogPost | Record<string, never>
  return 'id' in post ? post as BlogPost : null
}

