  const response = await fetch(`${baseUrl}/posts/${encodeURIComponent(id)}/comments`, {
    next: { revalidate: 300 },
  })
  if (!response.ok) throw new Error('Failed to load comments')
  return (await response.json()) as BlogComment[]
}

